<template>
  <div class="mobile-page progress-entry-page">
    <div class="mobile-head"><button class="back-button" @click="$router.back()">‹</button><div><b>进度填报</b><span>{{ isTown ? '维护本乡镇主体进度' : '维护乡镇进度并查看下级明细' }}</span></div><el-button link type="primary" @click="recordsVisible = true">上报记录</el-button></div>
    <section class="context-card"><div class="context-title"><b>可填报计划</b><el-tag size="small" type="info">{{ planOptions.length }} 条</el-tag></div><p>选择已形成的本级计划，填写本次新增播种或收获进度；主体明细可逐条维护。</p></section>
    <section v-for="item in planOptions" :key="item.id" class="plan-card">
      <div class="plan-title"><div><b>{{ item.year }}年{{ item.quarter }} · {{ item.cropName || item.crop }}</b><p>{{ item.planName }}</p></div><el-tag size="small" type="info">计划任务</el-tag></div>
      <div class="plan-meta"><span>计划 {{ Number(item.planArea || 0).toLocaleString() }} 亩</span><span>累计播种 {{ Number(item.sownArea || 0).toLocaleString() }} 亩</span><span>累计收获 {{ Number(item.harvestedArea || 0).toLocaleString() }} 亩</span></div>
      <div class="progress-row"><span>播种</span><el-progress :percentage="percent(item.sownArea, item.planArea)" :stroke-width="9" /><b>{{ Number(item.sownArea || 0).toFixed(1) }}亩</b></div>
      <div class="progress-row"><span>收获</span><el-progress :percentage="percent(item.harvestedArea, item.planArea)" status="success" :stroke-width="9" /><b>{{ Number(item.harvestedArea || 0).toFixed(1) }}亩</b></div>
      <el-button type="primary" class="fill-button" @click="openEntry(item)">填写进度</el-button>
    </section>
    <el-empty v-if="!planOptions.length" description="暂无可填报计划" :image-size="55" />

    <el-dialog v-model="recordsVisible" title="进度上报记录" width="94%" destroy-on-close>
      <div v-for="record in records" :key="record.id" class="record-card"><div><b>{{ record.year }}年{{ record.quarter }} · {{ record.type === 'sow' ? '播种' : '收获' }}</b><p>{{ record.planName }}</p><small>{{ record.updatedAt || record.recordedAt || '待更新' }} · 新增 {{ Number(record.incrementArea || 0).toFixed(1) }} 亩</small></div><el-button link type="primary" @click="showRecord(record)">查看详情</el-button></div><el-empty v-if="!records.length" description="暂无进度上报记录" :image-size="45" />
    </el-dialog>
    <el-dialog v-model="detailVisible" title="进度上报详情" width="94%"><template v-if="currentRecord"><el-descriptions :column="1" border><el-descriptions-item label="计划">{{ currentRecord.planName }}</el-descriptions-item><el-descriptions-item label="类型">{{ currentRecord.type === 'sow' ? '播种' : '收获' }}</el-descriptions-item><el-descriptions-item label="本次新增">{{ Number(currentRecord.incrementArea || 0).toFixed(1) }} 亩</el-descriptions-item><el-descriptions-item label="填报时间">{{ currentRecord.updatedAt || '—' }}</el-descriptions-item><el-descriptions-item label="填报说明">{{ currentRecord.remark || '—' }}</el-descriptions-item></el-descriptions><div class="detail-subtitle">{{ isTown ? '种植主体进度明细' : '乡镇进度明细' }}</div><div v-for="row in currentRecord.subjectRows || []" :key="row.id || row.subjectId || row.townCode" class="subject-detail-row"><span>{{ row.subjectName || row.townName }}</span><b>{{ Number(row.area || 0).toFixed(1) }} 亩</b></div><el-empty v-if="!(currentRecord.subjectRows || []).length" :description="isTown ? '本次未填写主体明细' : '本次未填写乡镇明细'" :image-size="40" /></template></el-dialog>

    <el-dialog v-model="entryVisible" title="填写本次进度" width="94%" destroy-on-close>
      <template v-if="selectedPlan">
        <div class="plan-context"><b>{{ selectedPlan.planName }}</b><span>计划 {{ Number(selectedPlan.planArea || 0).toLocaleString() }} 亩</span></div>
        <div class="type-switch"><button :class="{active: form.type === 'sow'}" @click="form.type = 'sow'">播种</button><button :class="{active: form.type === 'harvest'}" @click="form.type = 'harvest'">收获</button></div>
        <el-form label-position="top"><el-form-item :label="form.type === 'sow' ? '本次新增播种面积（亩）' : '本次新增收获面积（亩）'"><el-input-number v-model="form.incrementArea" :min="0" :max="remainingArea" :precision="1" controls-position="right" style="width:100%" /></el-form-item><el-form-item label="填报说明"><el-input v-model="form.remark" type="textarea" :rows="2" placeholder="如：本周新增播种面积" /></el-form-item></el-form>
        <div class="section-title"><b>{{ isTown ? '乡镇下种植主体明细' : '县级下乡镇进度明细' }}</b><el-button size="small" @click="addSubjectRow">添加{{ isTown ? '主体' : '乡镇' }}</el-button></div>
        <div v-for="row in form.subjectRows" :key="row.id" class="subject-row"><el-select v-model="row.name" filterable allow-create default-first-option :placeholder="`选择或输入${isTown ? '种植主体' : '乡镇'}`" size="small"><el-option v-for="item in subjectOptions" :key="item.id || item.code" :label="item.name" :value="item.name" /></el-select><el-input-number v-model="row.area" :min="0" :precision="1" controls-position="right" size="small" /><el-button link type="danger" @click="removeSubjectRow(row)">删除</el-button></div>
        <el-empty v-if="!form.subjectRows.length" :description="`可选填${isTown ? '主体' : '乡镇'}明细`" :image-size="40" />
      </template>
      <template #footer><el-button @click="entryVisible = false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存本次进度</el-button></template>
    </el-dialog>
  </div>
</template>

<script setup>
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { ElMessage } from 'element-plus'
import { useUserStore } from '@/stores/user'
import { fetchProgressPlanOptions, fetchProgressReportRows, saveSowingProgress, saveHarvestProgress } from '@/api/gpm'
import { GROW_SUBJECTS } from '@/mock/geo/plot-gen'
import { listTowns } from '@/mock/common/regions'
const userStore = useUserStore(); const isTown = computed(() => userStore.role?.code === 'town'); const year = 2026; const quarter = '第三季度'; const planOptions = ref([]); const rows = ref([]); const records = ref([]); const selectedPlan = ref(null); const entryVisible = ref(false); const recordsVisible = ref(false); const detailVisible = ref(false); const currentRecord = ref(null); const saving = ref(false); const subjectOptions = computed(() => isTown.value ? GROW_SUBJECTS.filter(x => String(x.regionCode).startsWith(String(userStore.role?.regionCode || '341222'))) : listTowns(String(userStore.role?.regionCode || '341222'))); const form = reactive({ type: 'sow', incrementArea: 0, remark: '', subjectRows: [] })
const remainingArea = computed(() => Math.max(0, Number(selectedPlan.value?.planArea || 0) - Number(selectedPlan.value?.doneArea || 0)))
const percent = (done, plan) => plan ? Number(Math.min(100, Number(done || 0) / Number(plan) * 100).toFixed(1)) : 0
const load = async () => { const [options, reportRows] = await Promise.all([fetchProgressPlanOptions(userStore.role, { year, quarter, type: form.type }), fetchProgressReportRows(userStore.role, { year, quarter, type: form.type })]); planOptions.value = (options || []).map(item => ({ ...item, sownArea: Number(item.sownArea || 0), harvestedArea: Number(item.harvestedArea || 0) })); rows.value = reportRows || []; records.value = rows.value.filter(x => x.level === userStore.role?.code).map(x => ({ ...x, type: form.type, incrementArea: x.incrementArea || x.reportedArea || 0, subjectRows: rows.value.filter(child => child.level === (isTown.value ? 'subject' : 'town') && child.planId === x.planId).map(child => ({ subjectId: child.subjectId, subjectName: child.subjectName || child.regionName, townName: child.townName || child.regionName, area: child.reportedArea || child.sownArea || child.harvestedArea || 0 })) })) }
const openEntry = item => { selectedPlan.value = item; form.incrementArea = 0; form.remark = ''; form.subjectRows = []; entryVisible.value = true }
const addSubjectRow = () => form.subjectRows.push({ id: `subject-${Date.now()}`, name: '', area: 0 })
const removeSubjectRow = row => { form.subjectRows = form.subjectRows.filter(x => x !== row) }
const showRecord = record => { currentRecord.value = record; detailVisible.value = true }
const save = async () => { if (!selectedPlan.value) return; if (Number(form.incrementArea || 0) <= 0 && !form.subjectRows.some(x => Number(x.area) > 0)) return ElMessage.warning('请填写本次进度或主体明细'); saving.value = true; const payload = { planId: selectedPlan.value.planId, planName: selectedPlan.value.planName, regionCode: selectedPlan.value.regionCode, regionName: selectedPlan.value.regionName, crop: selectedPlan.value.crop || selectedPlan.value.cropName, cropName: selectedPlan.value.cropName || selectedPlan.value.crop, planArea: Number(selectedPlan.value.planArea || 0), year: selectedPlan.value.year, quarter: selectedPlan.value.quarter, remark: form.remark, progressIncrement: Number(form.incrementArea || 0), subjectRows: form.subjectRows.map(row => ({ ...row, subjectName: row.name, townName: row.name })), ...(form.type === 'sow' ? { sownArea: Number(form.incrementArea || 0) } : { harvestedArea: Number(form.incrementArea || 0) }) }; const result = form.type === 'sow' ? await saveSowingProgress(payload, userStore.role) : await saveHarvestProgress(payload, userStore.role); saving.value = false; if (!result.success) return ElMessage.error(result.message || '保存失败'); ElMessage.success('本次进度已保存'); entryVisible.value = false; await load() }
watch(() => form.type, load); onMounted(load)
</script>

<style lang="scss" scoped>
.mobile-page{min-height:100%;box-sizing:border-box;background:#f5f7fa;padding:14px}.mobile-head,.context-card,.plan-card{background:#fff;border-radius:14px;padding:15px;margin-bottom:12px}.mobile-head{display:flex;align-items:center;gap:8px;color:#1f3c68}.mobile-head>div{flex:1;min-width:0}.mobile-head b{display:block;font-size:19px}.mobile-head span{display:block;color:#667085;font-size:11px;margin-top:4px}.back-button{border:0;background:none;font-size:34px;line-height:1;padding:0 6px 4px 0}.context-card{border:1px solid #d6eee5;background:#f8fcfa}.context-title,.plan-title,.plan-meta,.progress-row,.section-title,.record-card,.subject-row,.subject-detail-row{display:flex;align-items:center;justify-content:space-between;gap:8px}.context-title,.section-title{color:#243b5a}.context-card p{margin:7px 0 0;color:#667085;font-size:12px;line-height:1.5}.plan-card{border:1px solid #e5ebf2}.plan-title>div{flex:1;min-width:0}.plan-title b{color:#243b5a;font-size:14px}.plan-title p{margin:5px 0 0;color:#667085;font-size:11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.plan-meta{justify-content:flex-start;flex-wrap:wrap;color:#98a2b3;font-size:11px;margin:12px 0 4px}.progress-row{margin-top:10px;color:#667085;font-size:12px}.progress-row span{width:34px}.progress-row :deep(.el-progress){flex:1}.progress-row b{width:60px;text-align:right;color:#176b58;font-size:11px}.fill-button{width:100%;margin-top:13px}.plan-context{padding:12px;background:#eaf6f1;border-radius:9px;color:#176b58}.plan-context span{float:right;color:#667085;font-size:12px}.type-switch{display:flex;gap:8px;margin:12px 0}.type-switch button{flex:1;border:1px solid #d9e2ec;border-radius:8px;background:#fff;padding:10px;color:#667085}.type-switch button.active{border-color:#2d8c72;background:#eaf6f1;color:#176b58;font-weight:600}.subject-row{padding:9px 0;border-top:1px solid #edf0f5}.subject-row :deep(.el-select){flex:1}.subject-row :deep(.el-input-number){width:100px}.record-card{border-top:1px solid #edf0f5;padding:11px 0}.record-card>div{flex:1;min-width:0}.record-card b{color:#243b5a;font-size:13px}.record-card p,.record-card small{display:block;color:#667085;font-size:11px;margin:4px 0}.record-card small{color:#98a2b3}.detail-subtitle{font-weight:600;color:#243b5a;margin:14px 0 6px}.subject-detail-row{border-top:1px solid #edf0f5;padding:9px 0;color:#667085;font-size:12px}.subject-detail-row b{color:#176b58}
</style>